import{z as n,x as A,o as E,c as p,q as i,j as l,D as e,d as t,s as B,S as s,b as r}from"./chunks/framework.C8m1ZpeB.js";const F=JSON.parse('{"title":"列存格式：Parquet 解剖","description":"","frontmatter":{"title":"列存格式：Parquet 解剖","date":"2026-09-18T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/st-parquet-anatomy.md","filePath":"cs/st-parquet-anatomy.md","lastUpdated":1791063341000}'),m={name:"cs/st-parquet-anatomy.md"};function d(C,a,c,u,f,D){const o=A("Mermaid");return E(),p("div",null,[a[2]||(a[2]=i('<h1 id="列存格式-parquet-解剖" tabindex="-1">列存格式：Parquet 解剖 <a class="header-anchor" href="#列存格式-parquet-解剖" aria-label="Permalink to &quot;列存格式：Parquet 解剖&quot;">​</a></h1><div class="epigraph"><p>Parquet 把「表」变成一个自描述文件：先读尾部元数据，再按列寻址。格式自己就是合同，读完这份合同，引擎可以换、存储可以换。</p><footer>—— 据 Melnik et al., Dremel, VLDB 2010；Apache Parquet 格式规范（parquet-format）整理</footer></div><p><a href="/cs/st-ssd-ftl">上一课</a>收在块接口下有介质税单。前几课的结构都活在引擎自己的页合同里；分析型数据要离开引擎、装进开放文件时，格式必须自己当合同。主干已钉过 <a href="/cs/columnar-pax">列存与 PAX</a> 的页内列化、<a href="/cs/column-compression">列压缩</a>的字典与 RLE、<a href="/cs/parquet-orc">Parquet / ORC</a> 的 row group、列块与统计合同。本课解剖文件本体：字节怎么排、嵌套怎么存、统计怎么细到页、行组怎么定大小。后课默认：读 Parquet 就是先读合同再取列块。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>主干说了「读 footer 的统计跳 row group」。缺口在合同的具体条款。其一，字节布局：文件以 4 字节 magic 开头，中间是若干 row group，尾部是元数据、4 字节长度加 magic——所以一切 reader 的第一步是 seek 到文件末尾倒着读，拿到 schema、每列块的偏移与统计后，按列独立发起点状读取，对象存储上这正是并行度的来源。其二，嵌套：扁平列存装不下嵌套记录，Dremel 的 repetition/definition levels 把嵌套路径压成两列小整数——definition 记这条值路径上有几层 optional 字段有定义，repetition 记相对上一条记录在同一重复层走回了第几级，重组靠它们，不靠把记录拼回 JSON。<span class="marginnote">术语翻译：definition level 就是「这条值路径上有几层 optional 字段真的有值」，repetition level 就是「和上一条记录比，这次在第几层开了新的重复项」——两个各占几比特的小整数，加起来足以无损重组嵌套结构。</span>其三，统计的粒度：只有 row group 一层 min/max，跳过太粗；细到页才有得挑。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>条款按读取路径排。元数据层：footer 里的 FileMetaData 记每行组每列块的类型、编码、压缩、偏移与统计；列索引（ColumnIndex / OffsetIndex）把 min/max 与行号范围再细分到页，谓词在页级就能说不命中——这是 <a href="/cs/zone-maps">zone map</a> 的文件版。页层：列块内先字典页（若字典编码）再数据页，数据页 v1/v2 的差别在 level 与值的编码组织方式，页级还有布隆过滤器页兜点查。行组大小与底层分配单位对齐（HDFS 块或对象大小，常在一两百 MiB 量级）：太小则元数据与请求数爆炸、统计层失去过滤价值；太大则写入端缓冲大、失败重试与内存物化的粒度变粗。<span class="marginnote">数字实例：一个 128 MiB 行组、100 列的表，查询只取 3 列就读约 4 MiB——列块独立寻址让 I/O 直接缩到所需列的比例；同样的字节按行存，就得先把整行搬回来再丢掉不要的列。</span>文件不可变，更新与事务交给元数据层组织——主干课已钉过这句合同，本课补的是它的物理前提：列块可独立寻址，替换一个行组不必重写全文件。</p>',7)),(E(),l(s,null,{default:e(()=>[B(o,{id:"mermaid-19",class:"mermaid",graph:"flowchart%20TD%0A%20%20HEAD%5B%22magic%20PAR1%22%5D%20--%3E%20RG%5B%22row%20group%201..n%22%5D%0A%20%20RG%20--%3E%20CC%5B%22%E5%88%97%E5%9D%97%EF%BC%9A%E6%AF%8F%E5%88%97%E4%B8%80%E6%AE%B5%22%5D%0A%20%20CC%20--%3E%20PG%5B%22%E5%AD%97%E5%85%B8%E9%A1%B5%20%E2%86%92%20%E6%95%B0%E6%8D%AE%E9%A1%B5%20%E2%86%92%20%E5%B8%83%E9%9A%86%22%5D%0A%20%20RG%20--%3E%20FOOT%5B%22footer%EF%BC%9AFileMetaData%20%2B%20%E5%88%97%E7%B4%A2%E5%BC%95%22%5D%0A%20%20FOOT%20--%3E%20TAIL%5B%22magic%20PAR1%22%5D%0A%20%20READER%5B%22reader%22%5D%20--%3E%7C%22%E5%85%88%E8%AF%BB%E5%B0%BE%E9%83%A8%22%7C%20FOOT%0A%20%20FOOT%20--%3E%7C%22%E6%8C%89%E5%88%97%E5%9D%97%E5%81%8F%E7%A7%BB%E7%82%B9%E8%AF%BB%22%7C%20CC%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=r("h2",{id:"机制",tabindex:"-1"},[t("机制 "),r("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=r("p",null,[t("为什么条款这样定。列块独立寻址，是因为分析查询只碰少数列：只拉需要的列、只读命中的页，I/O 才从「扫整表」缩到「扫谓词可能命中的页」。统计的粒度是过滤收益与元数据量的折中：粒度越细，跳过越准，footer 与索引也越占读取预算。rep/def levels 让嵌套不破坏列独立：每列自带两级小整数（各占一字节内），重组只读涉及的列，谓词还能在重组之前先过滤——嵌套于是没有把列存拖回行存。不可变加自描述 footer，让文件成为 catalog 的最小单位：引擎、计算框架、元数据服务各自独立演进，互不锁死。"),r("span",{class:"marginnote"},"直觉类比：倒读 footer 像先看书末目录再翻页——不把整本书读完，先确定要的章在第几页，直接翻过去；对象存储上每一次「翻页」就是一次带偏移的点读，可以成百上千路并行发出。")],-1)),(E(),l(s,null,{default:e(()=>[B(o,{id:"mermaid-26",class:"mermaid",graph:"flowchart%20TD%0A%20%20P%5B%22%E8%B0%93%E8%AF%8D%EF%BC%9Acity%20%3D%20'%E4%B8%8A%E6%B5%B7'%22%5D%20--%3E%20F%5B%22%E8%AF%BB%20footer%20%E4%B8%8E%E5%88%97%E7%B4%A2%E5%BC%95%22%5D%0A%20%20F%20--%3E%20RGQ%7B%22%E8%A1%8C%E7%BB%84%20min%2Fmax%20%E5%91%BD%E4%B8%AD%EF%BC%9F%22%7D%0A%20%20RGQ%20--%3E%7C%22%E5%90%A6%22%7C%20SKIP%5B%22%E6%95%B4%E4%B8%AA%E8%A1%8C%E7%BB%84%E8%B7%B3%E8%BF%87%22%5D%0A%20%20RGQ%20--%3E%7C%22%E6%98%AF%22%7C%20CCQ%7B%22%E9%A1%B5%E7%BA%A7%E5%88%97%E7%B4%A2%E5%BC%95%E5%91%BD%E4%B8%AD%EF%BC%9F%22%7D%0A%20%20CCQ%20--%3E%7C%22%E5%90%A6%22%7C%20SKIPC%5B%22%E8%AF%A5%E5%88%97%E5%9D%97%E5%8F%AA%E7%95%99%E7%B4%A2%E5%BC%95%22%5D%0A%20%20CCQ%20--%3E%7C%22%E6%98%AF%22%7C%20BQ%7B%22%E5%B8%83%E9%9A%86%E8%BF%87%E6%BB%A4%E5%99%A8%E9%80%9A%E8%BF%87%EF%BC%9F%22%7D%0A%20%20BQ%20--%3E%7C%22%E5%90%A6%22%7C%20SKIPD%5B%22%E8%B7%B3%E8%BF%87%E8%AF%A5%E9%A1%B5%22%5D%0A%20%20BQ%20--%3E%7C%22%E6%98%AF%22%7C%20READ%5B%22%E8%A7%A3%E5%8E%8B%E8%AF%A5%E9%A1%B5%EF%BC%8C%E9%80%90%E8%A1%8C%E8%BF%87%E6%BB%A4%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=i('<p><span class="marginnote">易错点：小文件病不是 Parquet 的错而是行组规划的错——每个文件自带一份 footer 与列索引，行组按 MiB 以下切分时，元数据读取的时间会超过它帮你省下的数据扫描。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不重比 Parquet 与 ORC 的编码取舍（<a href="/cs/parquet-orc">主干对照课</a>已钉），不重讲字典与 RLE 的定义（<a href="/cs/column-compression">列压缩课</a>是前置），位图与倒排等索引另课。ORC 的轻量级索引与 ACID 扩展不展开。后课默认：文件是自描述、按列可寻址的不可变单元。下一课进入列块内部：编码与压缩的两层栈怎么叠、查询怎么不解码就过滤。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>读法先倒读 footer：schema、列块偏移与统计都在尾部，列块可独立点读。</li><li>嵌套靠 rep/def levels 两个小整数：列独立保持，谓词可在重组前过滤。</li><li>列索引把 min/max 细到页；统计粒度是过滤收益与元数据量的折中。</li><li>行组对齐存储分配单位；太小元数据爆炸，太大缓冲与重试粒度变粗。</li><li>出处：Melnik et al., Dremel, VLDB 2010；Apache Parquet 格式规范；Apache ORC 文档。</li></ul>',5))])}const P=n(m,[["render",d]]);export{F as __pageData,P as default};
